/* Модуль «Персонал» — экраны. Поток B. Помощники интерфейса приходят в init(ui) (см. docs/ARCHITECTURE.md).
   Логика недель/норм — modules/hr/domain.js (window.MostHR). Данные — только /api/hr/* (на сайте ERP финансовых API нет);
   деньги (оклады, ставка часа, себестоимость) сервер отдаёт только owner/partner/accountant — интерфейс лишь прячет разделы. */
(window.MOST_MODULES = window.MOST_MODULES || []).push({
  id: 'hr',
  title: 'Персонал',
  nav: [
    { id: 'hrtime', label: 'Табель', icon: '⏱' },
    { id: 'hrreview', label: 'Табели команды', icon: '☑', can: u => !!window.MostHR && (window.MostHR.canViewAll(u) || window.MostHR.isLead(u)) },
    { id: 'hrload', label: 'Загрузка', icon: '▥', can: u => !!window.MostHR && window.MostHR.canPlan(u) },
    { id: 'hrteams', label: 'Команды', icon: '👥' },
    { id: 'hrcost', label: 'Ставки и себестоимость', icon: '₸', can: u => !!window.MostHR && window.MostHR.isMoney(u) },
  ],
  routes: ['hremp'], // карточка сотрудника: #/hremp?id=…
  canOpen: u => !!window.MostHR && window.MostHR.canOpen(u),
  // инструкция модуля (раздел «Инструкция» и кнопка «?» в шапке раздела): [заголовок, html, id раздела меню]
  help: [
    ['Как устроен учёт времени', `
<p>Каждый сотрудник раз в неделю заполняет <b>табель</b>: сколько часов и на какой проект потратил (проекты — из модуля «Проекты»), плюс «Офис / без проекта» и отсутствия. Руководитель раздела <b>принимает</b> табели своей команды, владелец и партнёр — любые.</p>
<ul>
<li><b>Команды</b> — кто в каком разделе (АР, ГИП, ОВ, ВК, ГП, офис…) и кто руководитель. Состав можно загрузить из листа «ФОТ» таблицы бюджетов.</li>
<li><b>Загрузка</b> — факт часов по людям и проектам за прошлые недели и план на два месяца вперёд из сроков пунктов проектов.</li>
<li><b>Ставки и себестоимость</b> (владелец, партнёр, бухгалтер) — стоимость часа каждого сотрудника (оклад с налогами и премиями / норма часов месяца) и себестоимость часов по проектам и разделам. Остальные роли денег не видят — сервер их не отдаёт.</li>
<li>Уведомлений нет: цифра у «Табеля» — сколько ваших недель не сдано (с пятницы считается и текущая), у «Табелей команды» — сколько табелей ждут вашего решения.</li>
<li>Чтобы сотрудник видел свой табель, его аккаунт должен быть привязан к сотруднику: «Настройки → Пользователи» на сайте «Финансы» (поле «Сотрудник») или карточка сотрудника в «Командах» (поле «Пользователь»).</li>
</ul>`],
    ['Табель', `
<ol>
<li>Откройте нужную неделю стрелками (по умолчанию — текущая). Строка — проект или «Офис / без проекта» / «Отпуск / больничный», раздел работы (АР, КЖ, ОВ… — по умолчанию раздел вашей команды), часы по дням (шаг 0,25), заметка.</li>
<li>«+ Строка» добавляет проект; «Как на прошлой неделе» копирует строки прошлой недели. Проекты, где вы ГИП/ПМ, исполнитель пунктов или уже списывали часы, отмечены ★ и стоят первыми.</li>
<li><b>Сохранить</b> — черновик, <b>Сдать на проверку</b> — табель уходит руководителю. Пока табель не принят, его можно править (сданный вернётся в черновики — сдайте снова). Возвращённый табель (с причиной) исправьте и сдайте ещё раз.</li>
<li>Внизу — итог по дням и за неделю против нормы (40 ч при полной ставке, меньше в недели с праздниками). Больше 24 часов в день не сохранится.</li>
<li>Руководитель раздела и владелец могут открыть табель сотрудника команды (список «Сотрудник»), заполнить за него и принять.</li>
</ol>`, 'hrtime'],
    ['Табели команды', `
<p>Статусы табелей людей вашей команды за последние четыре недели: пусто — не заполнен, серый — черновик, жёлтый — сдан и ждёт вас, зелёный — принят, красный — возвращён. Щёлкните ячейку — откроется табель. Для выбранной недели: ✓ принять, ↺ вернуть с причиной. «Принять все сданные» — если всё в порядке.</p>
<p>Руководитель раздела видит команды, где он руководитель или чей раздел совпадает с его разделом в настройках пользователя; владелец, партнёр, бухгалтер и секретарь — всех (принимают владелец и партнёр).</p>`, 'hrreview'],
    ['Загрузка', `
<p><b>Факт</b> — часы по людям за последние недели (цвет: серый — мало, зелёный — около нормы, жёлтый — выше, красный — сильно выше нормы; полоска снизу — статус табеля), по проектам и по разделам. Строка человека открывает его карточку.</p>
<p><b>План</b> — на 9 недель вперёд из сроков пунктов активных проектов: каждый открытый пункт считается как один специалист на полную ставку в течение его нормативных недель до срока; просроченные пункты попадают в текущую неделю. Ёмкость раздела — сумма норм часов членов команды минус отпуска. Красное — план выше ёмкости: нужно двигать сроки или людей. Раскройте раздел — увидите пункты, из которых сложилась цифра.</p>`, 'hrload'],
    ['Команды', `
<ol>
<li>Команда — название, раздел (определяет, какие пункты проектов считаются её работой и какой раздел подставляется в табель), руководитель (пользователь) и состав.</li>
<li>Владелец и партнёр создают команды («+ Команда»), правят и удаляют; руководитель команды может менять только состав. Один сотрудник может состоять в нескольких командах.</li>
<li>«⇪ Импорт из ФОТ» — загрузка состава из JSON, который готовит <code>node modules/hr/tools/import_fot.js</code> из листа «ФОТ» таблицы бюджетов (имена сопоставляются с базой сотрудников по ФИО и окладу — результат проверьте).</li>
<li>Карточка сотрудника (щелчок по имени или ✎): должность, норма часов в неделю, привязка к пользователю, заметка; владелец, партнёр и бухгалтер видят и правят деньги — оклад (из финансов, только чтение), премию в месяц, 13-ю зарплату, ставку вручную.</li>
</ol>`, 'hrteams'],
    ['Ставки и себестоимость', `
<p><b>Ставка часа</b> = затраты работодателя в месяц / норма часов месяца. Затраты: оклад «на руки» → начисленная ЗП и налоги работодателя по ставкам из «Налоги → Ставки» (ОПВР, СО, ООСМС, СН), плюс средняя премия в месяц (тоже с налогами) и 1/12 оклада, если сотруднику платится 13-я зарплата. Норма — рабочие дни месяца без праздников РК × часы в день (норма недели из карточки / 5). Ставку можно задать вручную в карточке — тогда она используется вместо расчётной.</p>
<p><b>Себестоимость проектов</b> — часы из сданных и принятых табелей × ставка сотрудника в месяце недели; галочка «с черновиками» добавляет несданные. Строка проекта раскрывается: по людям, по разделам, по месяцам; если в проекте заполнен бюджет разделов, показывается сравнение с планом «Внутренние». Ту же цифру модуль «Проекты» может получить функцией <code>laborCost</code>.</p>`, 'hrcost'],
  ],
  onNav() { if (this._badges) this._badges(); },
  init(ui) {
    const M = this; const HR = window.MostHR;
    const { esc, api, fdate, today, toast, modal, formHtml, tbl, empty, chip, sel, head, bind, params, route, money, qsOf, mname, $ } = ui;
    if (!document.getElementById('hr-style')) document.head.insertAdjacentHTML('beforeend', `<style id="hr-style">
.hr-sub{display:flex;gap:6px 10px;flex-wrap:wrap;align-items:center;font-size:13px}
.hr-wk{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}.hr-wk b{font-size:15px;min-width:220px}.hr-wk select{width:auto;max-width:280px}
.hr-grid table{min-width:820px}.hr-grid th,.hr-grid td{padding:6px 6px;vertical-align:middle}.hr-grid td.d{width:60px;text-align:center}.hr-grid th.d{text-align:center;padding:6px 2px}.hr-grid th.d small{display:block;font-weight:400;letter-spacing:0;text-transform:none}
.hr-grid input.h{width:56px;text-align:center;padding:5px 3px}.hr-grid td.we,.hr-grid th.we{background:var(--panel-2)}.hr-grid th.hol,.hr-grid td.hol{background:var(--warn-bg)}
.hr-grid select.pid{min-width:190px;max-width:300px;padding:5px 6px}.hr-grid select.sec{min-width:86px;width:auto;padding:5px 6px}.hr-grid input.note{min-width:130px;padding:5px 6px}
.hr-grid td.tot{text-align:center;font-weight:700}.hr-grid tfoot td{text-align:center}.hr-grid tfoot td:first-child{text-align:left}.hr-grid td.over{color:var(--crit)}
.hr-ro td.d{font-variant-numeric:tabular-nums}
.hr-cell{text-align:center!important;font-variant-numeric:tabular-nums;min-width:46px;cursor:pointer}.hr-cell.l0{color:var(--ink-faint)}.hr-cell.l1{background:var(--ok-bg)}.hr-cell.l2{background:var(--warn-bg)}.hr-cell.l3{background:var(--crit-bg);color:var(--crit);font-weight:700}
.hr-cell.st-draft{box-shadow:inset 0 -3px 0 var(--ink-faint)}.hr-cell.st-submitted{box-shadow:inset 0 -3px 0 var(--warn)}.hr-cell.st-accepted{box-shadow:inset 0 -3px 0 var(--ok)}.hr-cell.st-rejected{box-shadow:inset 0 -3px 0 var(--crit)}
.hr-team{padding:0;margin-bottom:12px}.hr-team h3{margin:0;padding:10px 14px;font-size:14px;border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center;flex-wrap:wrap}.hr-team h3 .grow{flex:1}.hr-team .tbl{border:0;box-shadow:none;border-radius:0 0 var(--r) var(--r)}.hr-team table{min-width:560px}
.hr-kv{display:grid;grid-template-columns:200px 1fr;gap:8px 14px;font-size:13.5px}.hr-kv b{color:var(--ink-soft);font-weight:500}@media(max-width:600px){.hr-kv{grid-template-columns:1fr}.hr-kv b{margin-bottom:-6px}}
.hr-legend{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--ink-soft);margin:-4px 0 12px}.hr-legend i{display:inline-block;width:12px;height:12px;border-radius:3px;vertical-align:-2px;margin-right:4px;border:1px solid var(--line)}
.hr-mem{display:flex;flex-wrap:wrap;gap:6px;max-height:260px;overflow:auto;padding:4px 0}.hr-mem label{display:inline-flex;align-items:center;gap:5px;font-size:12.5px;border:1px solid var(--line);border-radius:999px;padding:3px 9px;cursor:pointer}.hr-mem label:has(input:checked){border-color:var(--accent);background:var(--accent-soft)}.hr-mem input{width:auto;margin:0}
.hr-row{cursor:pointer}.hr-kpi .card .val{font-size:20px}
.hr-plan td.p{text-align:center;font-variant-numeric:tabular-nums;font-size:12.5px;min-width:54px}.hr-plan td.p small{display:block;color:var(--ink-faint);font-size:10.5px}
.hr-items{padding:0 0 4px}.hr-items table{min-width:0}
</style>`);

    // ---- общие помощники ----
    const me = () => ui.state.user || {};
    const people = () => (ui.state.people || []).slice();
    const pname = id => { if (!id) return ''; const p = people().find(x => x.id === id); return p ? p.name : (id === me().id ? me().name : '—'); };
    const LEAD_ROLES = ['owner', 'partner', 'pm', 'gip', 'lead'];
    const userOpts = roles => [['', '—'], ...people().filter(p => !roles || roles.includes(p.role)).map(p => [p.id, p.name + (p.roleLabel ? ` · ${p.roleLabel}` : '') + (p.section ? ` (${p.section})` : '')])];
    const ST_CHIP = { draft: ['neutral', 'черновик'], submitted: ['warn', 'сдан'], accepted: ['ok', 'принят'], rejected: ['crit', 'возвращён'], '': ['neutral', 'не заполнен'] };
    const TRACK = { concept: 'концепция', ep: 'ЭП', rp: 'РП', an: 'АН' };
    const h = v => HR.fmtH(v) || '—';
    const hz = v => HR.fmtH(v) || '';
    const rerender = async () => { const y = window.scrollY; await route(); window.scrollTo(0, y); };
    const empLink = (id, text) => `<a href="#/hremp?id=${encodeURIComponent(id)}">${esc(text)}</a>`;
    let badgeAt = 0;
    const badges = async force => { if (!force && Date.now() - badgeAt < 60000) return; badgeAt = Date.now(); try { const b = await api('/hr/badges'); ui.setBadge('hrtime', b.hrtime); ui.setBadge('hrreview', b.hrreview); } catch { /* нет доступа */ } };
    M._badges = () => badges(false);
    const weekNav = (id, week, extra) => { const q = w => `#/${id}?${qsOf(Object.assign({}, extra || {}, { week: w }))}`; const cur = HR.isoWeek(today()); return `<a class="btn sm" href="${q(HR.addWeeks(week, -1))}" title="Предыдущая неделя">←</a><b>${esc(HR.weekTitle(week))}</b><a class="btn sm" href="${q(HR.addWeeks(week, 1))}" title="Следующая неделя">→</a>${week !== cur ? `<a class="btn sm" href="${q(cur)}">Текущая</a>` : ''}`; };
    // уровень загрузки по отношению к норме → класс ячейки
    const lvl = (hours, norm) => !hours ? 'l0' : !norm ? 'l1' : hours / norm < 0.6 ? 'l0' : hours / norm <= 1.05 ? 'l1' : hours / norm <= 1.25 ? 'l2' : 'l3';
    const monthOpts = () => { const out = []; const t = today(); const [y, m] = t.split('-').map(Number); for (let i = -12; i <= 2; i++) { const d = new Date(Date.UTC(y, m - 1 + i, 1)); const ym = d.toISOString().slice(0, 7); out.push([ym, mname(ym)]); } return out.reverse(); };

    // ---- карточка сотрудника (модалка) — должность, норма, пользователь; деньги — только MONEY ----
    function empModal(e, o, after) {
      const f = [];
      if (o.canEdit) f.push({ name: 'position', label: 'Должность (в модуле)', half: true }, { name: 'hoursPerWeek', label: 'Норма часов в неделю', type: 'number', step: '0.5', min: 0, half: true }, { name: 'userId', label: 'Пользователь системы (для своего табеля)', type: 'select', options: userOpts() });
      if (o.canEditMoney) f.push({ name: 'bonusMonthly', label: 'Средняя премия в месяц, ₸ на руки', type: 'number', half: true }, { name: 'bonus13', label: '13-я зарплата (1 оклад в год)', type: 'select', options: [['false', 'Нет'], ['true', 'Да']], half: true }, { name: 'rateOverride', label: 'Ставка часа вручную, ₸ (0 — считать автоматически)', type: 'number' });
      if (o.canEdit) f.push({ name: 'note', label: 'Заметка', type: 'textarea' });
      if (!f.length) return toast('Нет прав менять карточку');
      const info = `<p class="faint" style="margin:0 0 10px"><b>${esc(e.name)}</b> · ${esc(e.company || '')}${e.hired ? ' · принят ' + fdate(e.hired) : ''}${o.canEditMoney && e.salary != null ? ` · оклад на руки ${money(e.salary)} (меняется в финансах)` : ''}${e.teams && e.teams.length ? ' · ' + esc(e.teams.map(t => t.name).join(', ')) : ''}</p>`;
      modal('Сотрудник', info + formHtml(f, Object.assign({}, e, { bonus13: e.bonus13 ? 'true' : 'false', rateOverride: e.rateOverride || '' })), async v => { if ('bonus13' in v) v.bonus13 = v.bonus13 === 'true'; await api('/hr/employees/' + e.id, { method: 'PUT', body: v }); toast('Сохранено'); if (after) after(); else rerender(); });
    }

    // ---- табель ----
    ui.SECTIONS.hrtime = async main => {
      const u = params(); const week = HR.isWeek(u.get('week')) ? u.get('week') : HR.isoWeek(today()); const emp = u.get('emp') || '';
      let d;
      try { d = await api('/hr/timesheet?' + qsOf({ week, employeeId: emp })); }
      catch (e) { main.innerHTML = head('Табель') + `<div class="notice warn">${esc(e.message)}</div>` + (/не привязан/.test(e.message) ? `<p class="faint">Владелец привязывает аккаунт к сотруднику в «Настройки → Пользователи» (сайт «Финансы», поле «Сотрудник») или в карточке сотрудника здесь, в «Командах» (поле «Пользователь»). В режиме разработки можно подставить cookie <code>devemployee=&lt;id сотрудника&gt;</code>.</p>` : ''); return; }
      badges(false);
      const ts = d.ts; const can = d.can; let lines = (ts.lines || []).map(l => Object.assign({}, l, { hours: (l.hours || []).slice(0, 7) }));
      const projOpts = () => { const opts = [['', '— проект —'], ...d.projects.map(p => [p.id, `${p.mine ? '★ ' : ''}${p.name}${p.track ? ' · ' + TRACK[p.track] : ''}`])]; for (const l of lines) if (l.pid && !d.projects.some(p => p.id === l.pid)) opts.push([l.pid, (d.projectNames[l.pid] || l.pid) + ' · закрыт']); opts.push(['office', HR.KINDS.office], ['absence', HR.KINDS.absence]); return opts; };
      const status = ts.status || 'draft';
      const sub = `<div class="hr-sub">${chip(status, ST_CHIP)}${d.employee.position ? `<span>${esc(d.employee.position)}</span>` : ''}${d.employee.teams.length ? `<span>${esc(d.employee.teams.map(t => t.name).join(', '))}</span>` : ''}${ts.submittedAt ? `<span class="faint">сдан ${fdate(ts.submittedAt.slice(0, 10))}${d.names.submittedBy ? ' · ' + esc(d.names.submittedBy) : ''}</span>` : ''}${ts.acceptedAt ? `<span class="faint">принят ${fdate(ts.acceptedAt.slice(0, 10))}${d.names.acceptedBy ? ' · ' + esc(d.names.acceptedBy) : ''}</span>` : ''}</div>`;
      const btns = [can.edit ? '<button class="btn" data-act="hrSave">Сохранить</button>' : '', can.submit ? '<button class="btn primary" data-act="hrSubmit">Сдать на проверку</button>' : '', can.accept ? '<button class="btn primary" data-act="hrAccept">✓ Принять</button>' : '', can.reject ? '<button class="btn" data-act="hrReject">↺ Вернуть</button>' : '', can.reopen ? '<button class="btn" data-act="hrReopen" title="Снять отметку «принят», чтобы поправить">↺ В работу</button>' : ''].filter(Boolean).join(' ');
      const empSel = d.scope.length > 1 ? `<select id="hr-emp">${d.scope.map(s => `<option value="${esc(s.id)}"${s.id === d.employee.id ? ' selected' : ''}>${esc(s.name)}${s.id === d.me ? ' (я)' : ''}</option>`).join('')}</select>` : '';
      const dayHead = d.dates.map((dt, i) => `<th class="d${i >= 5 ? ' we' : ''}${d.holidays[i] ? ' hol' : ''}" title="${d.holidays[i] ? 'праздник' : ''}">${HR.DAYS[i]}<small>${dt.slice(8)}.${dt.slice(5, 7)}</small></th>`).join('');
      const rowHtml = (l, i) => {
        const val = l.kind === 'project' ? l.pid : l.kind; const cells = l.hours.map((v, k) => `<td class="d${k >= 5 ? ' we' : ''}${d.holidays[k] ? ' hol' : ''}">${can.edit ? `<input class="h" type="number" step="0.25" min="0" max="24" inputmode="decimal" data-i="${i}" data-k="${k}" value="${v || ''}">` : hz(v)}</td>`).join('');
        return `<tr data-i="${i}"><td>${can.edit ? `<select class="pid" data-i="${i}">${projOpts().map(([ov, ol]) => `<option value="${esc(ov)}"${String(ov) === String(val) ? ' selected' : ''}>${esc(ol)}</option>`).join('')}</select>` : `<b>${esc(l.kind === 'project' ? (d.projectNames[l.pid] || l.pid) : HR.KINDS[l.kind])}</b>`}</td><td>${can.edit ? `<select class="sec" data-i="${i}"${l.kind === 'absence' ? ' disabled' : ''}>${[['', '—'], ...HR.SECTIONS].map(o => { const [ov, ol] = Array.isArray(o) ? o : [o, o]; return `<option value="${esc(ov)}"${ov === (l.section || '') ? ' selected' : ''}>${esc(ol)}</option>`; }).join('')}</select>` : esc(l.section || '')}</td>${cells}<td class="tot" id="hr-lt-${i}">${hz(HR.lineTotal(l))}</td><td>${can.edit ? `<input class="note" data-i="${i}" placeholder="заметка" value="${esc(l.note || '')}">` : `<span class="faint">${esc(l.note || '')}</span>`}</td><td>${can.edit ? `<button class="btn sm danger" data-act="hrDel" data-i="${i}" title="Убрать строку">✕</button>` : ''}</td></tr>`;
      };
      const foot = () => { const tt = HR.tsTotals({ lines }); return `<tr><td>Итого</td><td></td>${tt.days.map((v, k) => `<td class="${v > 12 ? 'over' : ''}" title="${v > 12 ? 'больше 12 часов' : ''}">${hz(v)}</td>`).join('')}<td class="tot ${tt.total > d.norm * 1.25 ? 'over' : ''}">${hz(tt.total)}</td><td colspan="2" style="text-align:left" class="faint">норма ${hz(d.norm)} ч · проекты ${h(tt.project)} · офис ${h(tt.office)} · отсутствия ${h(tt.absence)}</td></tr>`; };
      const grid = () => `<div class="tbl hr-grid ${can.edit ? '' : 'hr-ro'}"><table><thead><tr><th>Проект / вид работы</th><th>Раздел</th>${dayHead}<th class="d">Итого</th><th>Заметка</th><th></th></tr></thead><tbody id="hr-body">${lines.length ? lines.map(rowHtml).join('') : `<tr><td colspan="12" class="faint" style="text-align:center;padding:18px">${can.edit ? 'Строк пока нет — нажмите «+ Строка»' + (d.prev ? ' или «Как на прошлой неделе»' : '') : 'Табель не заполнен'}</td></tr>`}</tbody><tfoot id="hr-foot">${foot()}</tfoot></table></div>` +
        (can.edit ? `<div class="hr-sub" style="margin-top:10px"><button class="btn sm" data-act="hrAdd">+ Строка</button>${d.prev && d.prev.lines.length ? `<button class="btn sm" data-act="hrCopy">Как на прошлой неделе (${esc(HR.weekLabel(d.prev.week))})</button>` : ''}<span class="faint">Часы по дням с шагом 0,25. Раздел — вид работы (по умолчанию раздел команды).</span></div>` : '');
      main.innerHTML = head(`Табель · ${d.employee.short}`, sub, btns) +
        (status === 'rejected' && ts.rejectNote ? `<div class="notice warn">Возвращён${d.names.rejectedBy ? ` (${esc(d.names.rejectedBy)})` : ''}: ${esc(ts.rejectNote)} — исправьте и сдайте снова.</div>` : '') +
        `<div class="hr-wk">${weekNav('hrtime', week, { emp })}${empSel}</div>` + grid();
      const redraw = () => { $('#hr-body').innerHTML = lines.length ? lines.map(rowHtml).join('') : '<tr><td colspan="12" class="faint" style="text-align:center;padding:18px">Строк нет</td></tr>'; $('#hr-foot').innerHTML = foot(); bind(main); };
      if ($('#hr-emp')) $('#hr-emp').onchange = () => { location.hash = `#/hrtime?${qsOf({ week, emp: $('#hr-emp').value })}`; };
      main.addEventListener('input', ev => { const el = ev.target; const i = Number(el.dataset.i); if (!(i >= 0) || !lines[i]) return;
        if (el.classList.contains('h')) { lines[i].hours[Number(el.dataset.k)] = Math.max(0, Math.min(24, Number(String(el.value).replace(',', '.')) || 0)); $('#hr-lt-' + i).textContent = hz(HR.lineTotal(lines[i])); $('#hr-foot').innerHTML = foot(); }
        else if (el.classList.contains('note')) lines[i].note = el.value; });
      main.addEventListener('change', ev => { const el = ev.target; const i = Number(el.dataset.i); if (!(i >= 0) || !lines[i]) return;
        if (el.classList.contains('pid')) { const v = el.value; if (v === 'office' || v === 'absence') { lines[i].kind = v; lines[i].pid = ''; if (v === 'absence') lines[i].section = ''; } else { lines[i].kind = 'project'; lines[i].pid = v; if (!lines[i].section) lines[i].section = d.defaultSection; } redraw(); }
        else if (el.classList.contains('sec')) lines[i].section = el.value; });
      const body = () => ({ employeeId: d.employee.id, week, lines });
      ui.ACT.hrAdd = () => { lines.push({ kind: 'project', pid: '', section: d.defaultSection, hours: [0, 0, 0, 0, 0, 0, 0], note: '' }); redraw(); const s = main.querySelector(`select.pid[data-i="${lines.length - 1}"]`); if (s) s.focus(); };
      ui.ACT.hrDel = ({ i }) => { lines.splice(Number(i), 1); redraw(); };
      ui.ACT.hrCopy = () => { for (const l of d.prev.lines) lines.push({ kind: l.kind || 'project', pid: l.pid || '', section: l.section || '', hours: (l.hours || []).slice(0, 7), note: '' }); redraw(); toast('Скопировано — проверьте часы'); };
      ui.ACT.hrSave = async () => { try { await api('/hr/timesheet', { method: 'PUT', body: body() }); toast('Сохранено (черновик)'); await rerender(); badges(true); } catch (e) { toast(e.message, 5000); } };
      ui.ACT.hrSubmit = async () => { try { await api('/hr/timesheet/submit', { method: 'POST', body: body() }); toast('Табель сдан на проверку'); await rerender(); badges(true); } catch (e) { toast(e.message, 5000); } };
      ui.ACT.hrAccept = async () => { try { if (can.edit && lines.length) await api('/hr/timesheet', { method: 'PUT', body: body() }); await api('/hr/timesheet/accept', { method: 'POST', body: { employeeId: d.employee.id, week } }); toast('Табель принят'); await rerender(); badges(true); } catch (e) { toast(e.message, 5000); } };
      ui.ACT.hrReject = () => modal('Вернуть табель', formHtml([{ name: 'note', label: 'Что исправить', required: true }], {}, 'Вернуть'), async v => { await api('/hr/timesheet/reject', { method: 'POST', body: { employeeId: d.employee.id, week, note: v.note } }); toast('Табель возвращён'); await rerender(); badges(true); });
      ui.ACT.hrReopen = async () => { try { await api('/hr/timesheet/reopen', { method: 'POST', body: { employeeId: d.employee.id, week } }); toast('Табель снова в работе'); await rerender(); } catch (e) { toast(e.message, 5000); } };
      bind(main);
    };

    // ---- табели команды ----
    ui.SECTIONS.hrreview = async main => {
      const u = params(); const week = HR.isWeek(u.get('week')) ? u.get('week') : HR.isoWeek(today());
      const d = await api('/hr/timesheets?' + qsOf({ week, n: 4 })); badges(true);
      const last = d.weeks[d.weeks.length - 1]; const sub = `<span class="${d.stat.submitted ? 'warn-text' : ''}">ждут решения ${d.stat.submitted}</span> · принято ${d.stat.accepted} · <span class="${d.stat.missing ? 'crit-text' : ''}">не сдано ${d.stat.missing}</span> из ${d.stat.total}<div class="faint">${d.all ? 'Все сотрудники.' : 'Ваши команды.'} Цвет: серый — черновик, жёлтый — сдан, зелёный — принят, красный — возвращён, пусто — не заполнен. Щёлкните ячейку, чтобы открыть табель.</div>`;
      const submittedIds = d.rows.filter(r => r.canAccept && r.weeks[r.weeks.length - 1].status === 'submitted').map(r => r.id);
      main.innerHTML = head('Табели команды', sub, submittedIds.length ? `<button class="btn primary" data-act="hrAcceptAll">✓ Принять все сданные (${submittedIds.length})</button>` : '') + `<div class="hr-wk">${weekNav('hrreview', week)}</div>` +
        (d.rows.length ? tbl([{ t: 'Сотрудник' }, { t: 'Команда' }, ...d.weeks.map(w => ({ t: `Нед. ${HR.weekNo(w)} · ${HR.weekLabel(w).slice(0, 5)}`, cls: w === last ? 'sorted' : '' })), { t: '' }],
          d.rows.map(r => { const cw = r.weeks[r.weeks.length - 1]; return `<tr><td>${empLink(r.id, r.short)}${r.position ? `<div class="faint">${esc(r.position)}</div>` : ''}</td><td class="nowrap">${esc(r.teams.map(t => t.name).join(', ') || '—')}</td>${r.weeks.map(w => `<td class="hr-cell ${w.status ? lvl(w.total, w.norm) : 'l0'} st-${w.status}" data-href="#/hrtime?${qsOf({ week: w.week, emp: r.id })}" title="${esc(ST_CHIP[w.status][1])}${w.rejectNote ? ': ' + esc(w.rejectNote) : ''} · норма ${hz(w.norm)} ч">${w.status ? `${hz(w.total) || '0'}` : '·'}</td>`).join('')}<td><div class="actions">${cw.status === 'submitted' && r.canAccept ? `<button class="btn sm primary" data-act="hrRvAccept" data-id="${esc(r.id)}" title="Принять">✓</button><button class="btn sm" data-act="hrRvReject" data-id="${esc(r.id)}" title="Вернуть">↺</button>` : ''}${chip(cw.status, ST_CHIP)}</div></td></tr>`; }))
          : empty('В вашей области видимости нет сотрудников. Проверьте состав команд.'));
      main.querySelectorAll('td[data-href]').forEach(td => td.onclick = () => { location.hash = td.dataset.href; });
      ui.ACT.hrRvAccept = async ({ id }) => { try { await api('/hr/timesheet/accept', { method: 'POST', body: { employeeId: id, week: last } }); toast('Принят'); await rerender(); badges(true); } catch (e) { toast(e.message, 5000); } };
      ui.ACT.hrRvReject = ({ id }) => modal('Вернуть табель', formHtml([{ name: 'note', label: 'Что исправить', required: true }], {}, 'Вернуть'), async v => { await api('/hr/timesheet/reject', { method: 'POST', body: { employeeId: id, week: last, note: v.note } }); toast('Возвращён'); await rerender(); badges(true); });
      ui.ACT.hrAcceptAll = async () => { if (!confirm(`Принять ${submittedIds.length} сданных табелей за неделю ${HR.weekNo(last)}?`)) return; let n = 0; for (const id of submittedIds) { try { await api('/hr/timesheet/accept', { method: 'POST', body: { employeeId: id, week: last } }); n++; } catch (e) { toast(e.message, 4000); } } toast(`Принято: ${n}`); await rerender(); badges(true); };
      bind(main);
    };

    // ---- загрузка: факт и план ----
    ui.SECTIONS.hrload = async main => {
      const u = params(); const tab = u.get('tab') === 'plan' ? 'plan' : 'fact'; const to = HR.isWeek(u.get('to')) ? u.get('to') : HR.isoWeek(today()); const n = Number(u.get('n')) || 8;
      const tabs = `<div class="tabs">${[['fact', 'Факт по неделям'], ['plan', 'План на 9 недель']].map(([id, l]) => `<a href="#/hrload?tab=${id}" class="${tab === id ? 'active' : ''}">${l}</a>`).join('')}</div>`;
      if (tab === 'fact') {
        const d = await api('/hr/load?' + qsOf({ to, n }));
        const wh = d.weeks.map(w => ({ t: `${HR.weekNo(w)} · ${HR.weekLabel(w).slice(0, 5)}`, cls: 'right' }));
        const rows = d.rows.filter(r => r.total || r.status !== 'resigned');
        main.innerHTML = head('Загрузка', `${d.all ? 'Все сотрудники' : 'Ваша область видимости'} · ${d.weeks.length} недель до ${esc(HR.weekLabel(to))} · всего ${h(d.totals.reduce((s, x) => s + x, 0))} ч`, `<a class="btn sm" href="#/hrload?${qsOf({ to: HR.addWeeks(to, -n) })}">← раньше</a> <a class="btn sm" href="#/hrload?${qsOf({ to: HR.addWeeks(to, n) })}">позже →</a> <a class="btn sm" href="#/hrload">Сегодня</a>`) + tabs +
          `<div class="hr-legend"><span><i style="background:var(--ok-bg)"></i>около нормы</span><span><i style="background:var(--warn-bg)"></i>выше нормы</span><span><i style="background:var(--crit-bg)"></i>сильно выше</span><span>полоска снизу — статус табеля: серый черновик, жёлтый сдан, зелёный принят, красный возвращён</span></div>` +
          (rows.length ? tbl([{ t: 'Сотрудник' }, { t: 'Команда' }, ...wh, { t: 'Итого', cls: 'amt' }], rows.map(r => `<tr class="hr-row" data-id="${esc(r.id)}"><td><b>${esc(r.short)}</b>${r.position ? `<div class="faint">${esc(r.position)}</div>` : ''}</td><td class="nowrap">${esc(r.teams.map(t => t.name).join(', ') || '—')}</td>${r.hours.map((x, i) => `<td class="hr-cell ${lvl(x, r.norm[i])} st-${r.status[i]}" title="норма ${hz(r.norm[i])} ч">${hz(x) || (r.status[i] ? '0' : '·')}</td>`).join('')}<td class="amt num">${h(r.total)}</td></tr>`), `<tr><td colspan="2">Итого</td>${d.totals.map(x => `<td class="right num">${hz(x)}</td>`).join('')}<td class="amt num">${h(d.totals.reduce((s, x) => s + x, 0))}</td></tr>`) : empty('Табелей за этот период нет')) +
          `<h2>По проектам</h2>` + (d.projects.length ? tbl([{ t: 'Проект' }, ...wh, { t: 'Итого', cls: 'amt' }, { t: 'Людей', cls: 'amt' }], d.projects.map(p => `<tr><td><b>${esc(p.name)}</b>${!p.pid ? ' <span class="chip neutral">не проект</span>' : ''}</td>${p.hours.map(x => `<td class="right num">${hz(x)}</td>`).join('')}<td class="amt num">${h(p.total)}</td><td class="amt num">${p.people}</td></tr>`)) : empty('Часов по проектам нет')) +
          (d.sections.length ? `<h2>По разделам (часы на проекты)</h2>` + tbl([{ t: 'Раздел' }, ...wh, { t: 'Итого', cls: 'amt' }], d.sections.map(s => `<tr><td><b>${esc(s.section)}</b></td>${s.hours.map(x => `<td class="right num">${hz(x)}</td>`).join('')}<td class="amt num">${h(s.total)}</td></tr>`)) : '');
        main.querySelectorAll('tr.hr-row').forEach(tr => tr.onclick = () => { location.hash = `#/hremp?id=${encodeURIComponent(tr.dataset.id)}`; });
        return;
      }
      const d = await api('/hr/plan?n=9');
      const wh = d.weeks.map((w, i) => ({ t: `${HR.weekNo(w)} · ${HR.weekLabel(w).slice(0, 5)}${d.holidays[i] ? ' ★' : ''}`, cls: 'right' }));
      const cellCls = pct => pct === 0 ? 'l0' : pct > 120 ? 'l3' : pct > 90 ? 'l2' : 'l1';
      main.innerHTML = head('Загрузка', `План из сроков пунктов ${d.projects} активных проектов · открытых пунктов с разделом и сроком: ${d.items}`, '<a class="btn sm" href="#/pmrp">Проекты →</a>') + tabs +
        `<div class="faint" style="margin:-6px 0 10px">Допущение: пункт = один специалист на полную ставку в течение его нормативных недель до срока. «Долг» — часы пунктов, у которых срок уже прошёл (их надо закрыть или перенести в карточке проекта). Ячейка: план ч / ёмкость команды ч (норма людей минус отпуска). ★ — неделя с праздником.</div>` +
        (d.sections.length ? `<div class="tbl hr-plan"><table><thead><tr><th>Раздел</th><th>Команда</th><th class="right" title="Часы просроченных пунктов">Долг</th>${wh.map(c => `<th class="right">${esc(c.t)}</th>`).join('')}<th class="amt">Итого план</th></tr></thead><tbody>${d.sections.map((s, si) => `<tr class="hr-row" data-i="${si}" title="Раскрыть пункты"><td><b>${esc(s.section)}</b><div class="faint">${s.items.length} пунктов${s.items.some(x => x.overdue) ? ` · <span class="crit-text">просрочено ${s.items.filter(x => x.overdue).length}</span>` : ''}</div></td><td class="nowrap">${s.people.length ? `${s.people.length} чел.<div class="faint">${esc(s.people.slice(0, 4).map(p => p.name.split(' ')[0]).join(', '))}${s.people.length > 4 ? '…' : ''}</div>` : '<span class="crit-text">нет команды</span>'}</td><td class="p hr-cell ${s.overdue ? 'l3' : 'l0'}" title="часы просроченных пунктов">${hz(s.overdue) || '·'}</td>${s.plan.map((p, i) => `<td class="p hr-cell ${cellCls(s.load[i])}" title="${s.load[i] === 999 ? 'нет ёмкости' : s.load[i] + ' % ёмкости'}">${hz(p) || '·'}<small>/ ${hz(s.capacity[i]) || '0'}</small></td>`).join('')}<td class="amt num">${h(s.total)}</td></tr><tr class="row-detail hr-items" data-for="${si}" hidden><td colspan="${d.weeks.length + 4}">${tbl([{ t: 'Срок' }, { t: 'Проект' }, { t: 'Пункт' }, { t: 'Этап' }, { t: 'Нед.', cls: 'amt' }, { t: 'Часов', cls: 'amt' }, { t: 'Исполнитель' }], s.items.map(it => `<tr class="${it.overdue ? 'row-old' : ''}"><td class="nowrap">${fdate(it.due)}${it.overdue ? ' <span class="chip crit">просрочен</span>' : ''}</td><td><a href="#/pmp?id=${encodeURIComponent(it.pid)}">${esc(it.project)}</a></td><td>${esc(it.title)}</td><td class="faint">${esc(it.stageName)}</td><td class="amt num">${it.weeks}</td><td class="amt num">${hz(it.hours)}</td><td>${esc(it.assignee || '—')}</td></tr>`))}</td></tr>`).join('')}</tbody></table></div>` : empty('Нет открытых пунктов со сроками в активных проектах — план пуст')) +
        (d.byEmployee.length ? `<h2>Назначенные исполнители</h2>` + tbl([{ t: 'Сотрудник' }, { t: 'Долг', cls: 'right' }, ...wh, { t: 'Пунктов', cls: 'amt' }], d.byEmployee.map(e => `<tr><td>${empLink(e.employeeId, e.name)}</td><td class="p hr-cell ${e.overdue ? 'l3' : 'l0'}">${hz(e.overdue) || '·'}</td>${e.plan.map((p, i) => `<td class="p hr-cell ${cellCls(e.capacity[i] ? Math.round(p / e.capacity[i] * 100) : (p ? 999 : 0))}">${hz(p) || '·'}<small>/ ${hz(e.capacity[i]) || '0'}</small></td>`).join('')}<td class="amt num">${e.items}</td></tr>`)) : '');
      main.querySelectorAll('tr.hr-row[data-i]').forEach(tr => tr.onclick = () => { const det = main.querySelector(`tr[data-for="${tr.dataset.i}"]`); det.hidden = !det.hidden; });
    };

    // ---- команды ----
    ui.SECTIONS.hrteams = async main => {
      const d = await api('/hr/teams'); const money = HR.isMoney(me());
      const memberRow = (m, t) => `<tr><td>${empLink(m.id, m.short)}${m.userName ? `<div class="faint">${esc(m.userName)}</div>` : '<div class="faint">без пользователя</div>'}</td><td>${esc(m.position || '—')}</td><td class="nowrap">${m.hoursPerWeek} ч/нед${m.teams.length > 1 ? `<div class="faint">ещё: ${esc(m.teams.filter(x => x.id !== t.id).map(x => x.name).join(', '))}</div>` : ''}</td><td>${m.hired ? fdate(m.hired) : '<span class="faint">—</span>'}</td><td><div class="actions">${d.canEdit || money ? `<button class="btn sm" data-act="hrEmpEdit" data-id="${esc(m.id)}" title="Карточка">✎</button>` : ''}${t.canEdit ? `<button class="btn sm danger" data-act="hrMemDel" data-team="${esc(t.id)}" data-id="${esc(m.id)}" title="Убрать из команды">✕</button>` : ''}</div></td></tr>`;
      const MEM_COLS = [{ t: 'Сотрудник' }, { t: 'Должность' }, { t: 'Норма' }, { t: 'Принят' }, { t: '' }];
      main.innerHTML = head('Команды', `${d.teams.length} команд · ${d.employees.length} работающих сотрудников · без команды ${d.unassigned.length}`, d.canEdit ? '<button class="btn" data-act="hrImport">⇪ Импорт из ФОТ</button> <button class="btn primary" data-act="hrTeamNew">+ Команда</button>' : '') +
        (d.teams.length ? d.teams.map(t => `<div class="card hr-team"><h3><span class="grow">${esc(t.name)} ${t.section ? chip(t.section, {}) : ''} <span class="faint">${t.members.length} чел.</span></span><span class="faint">руководитель: <b>${esc(t.leadName || '—')}</b></span>${t.canEdit ? `<button class="btn sm" data-act="hrMemAdd" data-team="${esc(t.id)}">+ Сотрудник</button><button class="btn sm" data-act="hrTeamEdit" data-id="${esc(t.id)}">✎</button>` : ''}${d.canEdit ? `<button class="btn sm danger" data-act="hrTeamDel" data-id="${esc(t.id)}" title="Удалить команду">✕</button>` : ''}</h3>${t.note ? `<div class="faint" style="padding:8px 14px 0">${esc(t.note)}</div>` : ''}${t.members.length ? tbl(MEM_COLS, t.members.map(m => memberRow(m, t))) : '<div class="faint" style="padding:12px 14px">Состав пуст</div>'}</div>`).join('') : empty(d.canEdit ? 'Команд пока нет — создайте («+ Команда») или загрузите состав из листа «ФОТ»' : 'Команд пока нет')) +
        (d.unassigned.length ? `<div class="card hr-team"><h3><span class="grow">Без команды <span class="faint">${d.unassigned.length}</span></span></h3>${tbl(MEM_COLS, d.unassigned.map(m => `<tr><td>${empLink(m.id, m.short)}${m.userName ? `<div class="faint">${esc(m.userName)}</div>` : ''}</td><td>${esc(m.position || '—')}</td><td>${m.hoursPerWeek} ч/нед</td><td>${m.hired ? fdate(m.hired) : '<span class="faint">—</span>'}</td><td><div class="actions">${d.canEdit || money ? `<button class="btn sm" data-act="hrEmpEdit" data-id="${esc(m.id)}">✎</button>` : ''}${d.teams.some(t => t.canEdit) ? `<button class="btn sm" data-act="hrMemTo" data-id="${esc(m.id)}">→ в команду</button>` : ''}</div></td></tr>`))}</div>` : '');
      const teamForm = t => { const chosen = new Set(t ? t.members.map(m => m.id) : []); return `<form>${formHtml([{ name: 'name', label: 'Название', required: true, half: true }, { name: 'section', label: 'Раздел (пункты проектов этого раздела — работа команды)', type: 'select', options: [['', '—'], ...d.sections], half: true }, { name: 'leadUserId', label: 'Руководитель (пользователь)', type: 'select', options: userOpts(LEAD_ROLES) }, { name: 'note', label: 'Заметка' }], t || {}).replace(/^<form>|<div class="error"><\/div><button[\s\S]*$/g, '')}<div class="field"><label>Состав (${d.employees.length} работающих)</label><div class="hr-mem">${d.employees.map(e => `<label><input type="checkbox" name="m_${esc(e.id)}"${chosen.has(e.id) ? ' checked' : ''}>${esc(e.short)}${e.position ? ` <span class="faint">${esc(e.position)}</span>` : ''}</label>`).join('')}</div></div><div class="error"></div><button class="btn primary block" type="submit">Сохранить</button></form>`; };
      const teamBody = v => { const members = Object.keys(v).filter(k => k.startsWith('m_')).map(k => k.slice(2)); return { name: v.name, section: v.section, leadUserId: v.leadUserId, note: v.note, members }; };
      ui.ACT.hrTeamNew = () => { modal('Новая команда', teamForm(null), async v => { await api('/hr/teams', { method: 'POST', body: teamBody(v) }); toast('Команда создана'); rerender(); }); $('#modal .modal-card').style.maxWidth = '720px'; };
      ui.ACT.hrTeamEdit = ({ id }) => { const t = d.teams.find(x => x.id === id); modal('Команда', teamForm(t), async v => { await api('/hr/teams/' + id, { method: 'PUT', body: teamBody(v) }); toast('Сохранено'); rerender(); }); $('#modal .modal-card').style.maxWidth = '720px'; };
      ui.ACT.hrTeamDel = async ({ id }) => { const t = d.teams.find(x => x.id === id); if (!confirm(`Удалить команду «${t.name}»? Табели сотрудников сохранятся.`)) return; await api('/hr/teams/' + id, { method: 'DELETE' }); toast('Удалено'); rerender(); };
      ui.ACT.hrMemAdd = ({ team }) => { const t = d.teams.find(x => x.id === team); const have = new Set(t.members.map(m => m.id)); const opts = d.employees.filter(e => !have.has(e.id)).map(e => [e.id, e.short + (e.teams.length ? ` (${e.teams.map(x => x.name).join(', ')})` : '')]); if (!opts.length) return toast('Все уже в команде'); modal(`В команду «${t.name}»`, formHtml([{ name: 'employeeId', label: 'Сотрудник', type: 'select', options: opts }], {}, 'Добавить'), async v => { await api(`/hr/teams/${team}/members`, { method: 'POST', body: v }); toast('Добавлен'); rerender(); }); };
      ui.ACT.hrMemTo = ({ id }) => { const e = d.employees.find(x => x.id === id); const opts = d.teams.filter(t => t.canEdit).map(t => [t.id, t.name]); modal(`${e.short} → команда`, formHtml([{ name: 'team', label: 'Команда', type: 'select', options: opts }], {}, 'Добавить'), async v => { await api(`/hr/teams/${v.team}/members`, { method: 'POST', body: { employeeId: id } }); toast('Добавлен'); rerender(); }); };
      ui.ACT.hrMemDel = async ({ team, id }) => { await api(`/hr/teams/${team}/members/${encodeURIComponent(id)}`, { method: 'DELETE' }); toast('Убран из команды'); rerender(); };
      ui.ACT.hrEmpEdit = async ({ id }) => { try { const c = await api('/hr/employees/' + encodeURIComponent(id)); empModal(c.employee, c); } catch (e) { toast(e.message, 4000); } };
      ui.ACT.hrImport = () => modal('Импорт команд из листа «ФОТ»', `<p class="faint" style="margin:0 0 10px">JSON готовит <code>node modules/hr/tools/import_fot.js</code> из листа «ФОТ» файла MOST_Проекты РП_Бюджет.xlsx (блок «Состав команд»). Команды с тем же названием дополняются; «заменить» — состав перезаписывается, должности обновляются.</p><form><div class="field"><label>Файл JSON</label><input type="file" id="hr-imp-file" accept=".json,application/json" required></div><div class="field"><label>Если команда уже есть</label><select name="mode"><option value="merge">Дополнить состав</option><option value="replace">Заменить состав</option></select></div><div class="error"></div><button class="btn primary block" type="submit">Импортировать</button></form>`, async v => {
        const f = $('#hr-imp-file').files[0]; if (!f) throw new Error('Выберите файл'); let data; try { data = JSON.parse(await f.text()); } catch { throw new Error('Файл не читается как JSON'); }
        if (!Array.isArray(data.teams)) throw new Error('В файле нет списка teams'); data.mode = v.mode;
        const r = await api('/hr/import', { method: 'POST', body: data }); toast(`Создано команд ${r.created.length}, дополнено ${r.updated.length}, участников ${r.members}, должностей ${r.positions}${r.skipped.length ? '; пропущено: ' + r.skipped.join(', ') : ''}`, 9000); rerender();
      });
      bind(main);
    };

    // ---- карточка сотрудника ----
    ui.SECTIONS.hremp = async main => {
      const id = params().get('id'); if (!id) { location.hash = '#/hrteams'; return; }
      const c = await api('/hr/employees/' + encodeURIComponent(id)); const e = c.employee; const r = c.rate;
      const row = (k, v) => v ? `<b>${esc(k)}</b><div>${v}</div>` : '';
      main.innerHTML = `<p class="faint" style="margin:0 0 6px"><a href="#/hrteams">← Команды</a></p>` + head(e.name, `<div class="hr-sub">${e.status === 'resigned' ? `<span class="chip neutral">уволен${e.resigned ? ' ' + fdate(e.resigned) : ''}</span>` : '<span class="chip ok">работает</span>'}${e.position ? `<span>${esc(e.position)}</span>` : ''}${e.teams.length ? `<span>${esc(e.teams.map(t => t.name).join(', '))}</span>` : ''}<span class="faint">${esc(e.company)}</span></div>`, [c.canEdit || c.canEditMoney ? '<button class="btn" data-act="hrEmpEdit2">✎ Карточка</button>' : '', c.hoursVisible ? `<a class="btn" href="#/hrtime?${qsOf({ emp: e.id })}">Табель →</a>` : ''].filter(Boolean).join(' ')) +
        `<div class="grid g2"><div class="card"><div class="hr-kv">${row('Пользователь', e.userName ? esc(e.userName) : '<span class="faint">не привязан — сотрудник не увидит свой табель</span>')}${row('Команды', e.teams.length ? e.teams.map(t => `${esc(t.name)}${t.section ? ` <span class="chip neutral">${esc(t.section)}</span>` : ''}`).join(', ') : '<span class="faint">без команды</span>')}${row('Норма', `${e.hoursPerWeek} ч в неделю`)}${row('Принят', e.hired ? fdate(e.hired) : '<span class="faint">дата не заполнена (финансы → сотрудники)</span>')}${row('Заметка', esc(e.note || ''))}</div></div>` +
        (r ? `<div class="card"><div class="label">Стоимость часа · ${esc(mname(r.ym))}</div><div class="val num">${money(r.rate)} <span class="faint" style="font-size:12px">/ ч${r.override ? ' · задана вручную' : ''}</span></div><div class="hr-kv" style="margin-top:10px"><b>Оклад на руки</b><div class="num">${money(r.salary)}</div><b>Начислено (с ИПН, ОПВ, ВОСМС)</b><div class="num">${money(r.gross)}</div><b>Налоги работодателя</b><div class="num">${money(r.employer)}</div><b>Премия в месяц</b><div class="num">${r.bonusMonthly ? money(r.bonusMonthly) + ' (с налогами ' + money(r.bonusCost) + ')' : '—'}</div><b>13-я зарплата, 1/12</b><div class="num">${r.bonus13 ? money(r.bonus13) : '—'}</div><b>Затраты в месяц</b><div class="num"><b>${money(r.monthCost)}</b></div><b>Норма часов</b><div class="num">${r.normHours} ч (${r.normDays} раб. дн.)</div>${r.override ? `<b>Расчётная ставка</b><div class="num">${money(r.rateCalc)}</div>` : ''}</div></div>` : '') + `</div>` +
        (c.hoursVisible ? `<h2>Последние 8 недель · ${h(c.hours8w)} ч</h2><div class="grid g2"><div>${tbl([{ t: 'Неделя' }, { t: 'Статус' }, { t: 'Часы', cls: 'amt' }, { t: 'Норма', cls: 'amt' }], c.weeks.slice().reverse().map(w => `<tr class="hr-row" data-href="#/hrtime?${qsOf({ week: w.week, emp: e.id })}"><td class="nowrap">${HR.weekNo(w.week)} · ${esc(HR.weekLabel(w.week))}</td><td>${chip(w.status, ST_CHIP)}</td><td class="amt num ${w.status && w.total < w.norm * 0.6 ? 'warn-text' : ''}">${w.status ? h(w.total) : '·'}</td><td class="amt num faint">${hz(w.norm)}</td></tr>`))}</div><div>${c.byProject.length ? tbl([{ t: 'Проект' }, { t: 'Часов', cls: 'amt' }], c.byProject.map(p => `<tr><td>${p.pid ? `<a href="#/pmp?id=${encodeURIComponent(p.pid)}">${esc(p.name)}</a>` : esc(p.name)}</td><td class="amt num">${h(p.hours)}</td></tr>`)) : empty('Часов за 8 недель нет')}</div></div>` : '');
      main.querySelectorAll('tr[data-href]').forEach(tr => tr.onclick = () => { location.hash = tr.dataset.href; });
      ui.ACT.hrEmpEdit2 = () => empModal(e, c);
      bind(main);
    };

    // ---- ставки и себестоимость (только owner/partner/accountant) ----
    ui.SECTIONS.hrcost = async main => {
      const u = params(); const tab = u.get('tab') === 'projects' ? 'projects' : 'rates';
      const tabs = `<div class="tabs">${[['rates', 'Ставка часа'], ['projects', 'Себестоимость проектов']].map(([id, l]) => `<a href="#/hrcost?tab=${id}" class="${tab === id ? 'active' : ''}">${l}</a>`).join('')}</div>`;
      if (tab === 'rates') {
        const ym = /^\d{4}-\d{2}$/.test(u.get('ym') || '') ? u.get('ym') : today().slice(0, 7); const d = await api('/hr/rates?ym=' + ym); const T = d.total;
        main.innerHTML = head('Ставки и себестоимость', `${esc(mname(ym))} · затраты на штат в месяц <b class="num">${money(T.monthCost)}</b> · часов в табелях ${h(T.hoursMonth)} на ${money(T.costMonth)}`) + tabs +
          `<div class="filters">${sel('hr-f-ym', monthOpts(), ym)}<span class="faint" style="align-self:center">Ставка = (оклад с налогами работодателя + премия + 1/12 оклада при 13-й ЗП) / норма часов месяца. Ставки налогов — «Налоги → Ставки» на сайте «Финансы».</span></div>` +
          tbl([{ t: 'Сотрудник' }, { t: 'Команда' }, { t: 'Оклад на руки', cls: 'amt' }, { t: 'Затраты работод.', cls: 'amt' }, { t: 'Премия / 13-я', cls: 'amt' }, { t: 'Всего в месяц', cls: 'amt' }, { t: 'Норма, ч', cls: 'amt' }, { t: 'Ставка ₸/ч', cls: 'amt' }, { t: 'Часов в мес.', cls: 'amt' }, { t: 'Стоимость часов', cls: 'amt' }, { t: '' }],
            d.rows.map(r => `<tr><td>${empLink(r.id, r.short)}${r.position ? `<div class="faint">${esc(r.position)}</div>` : ''}${r.status === 'resigned' ? ' <span class="chip neutral">уволен</span>' : ''}</td><td class="nowrap">${esc(r.teams.map(t => t.name).join(', ') || '—')}</td><td class="amt num">${money(r.salary)}</td><td class="amt num">${money(r.employerCost)}</td><td class="amt num">${r.bonusCost || r.bonus13 ? money(r.bonusCost + r.bonus13) : '—'}</td><td class="amt num"><b>${money(r.monthCost)}</b></td><td class="amt num">${r.normHours}${r.hoursPerWeek !== 40 ? `<div class="faint">${r.hoursPerWeek} ч/нед</div>` : ''}</td><td class="amt num"><b>${money(r.rate)}</b>${r.override ? `<div class="faint" title="расчётная ${money(r.rateCalc)}">вручную</div>` : ''}</td><td class="amt num">${hz(r.hoursMonth) || '—'}</td><td class="amt num">${r.costMonth ? money(r.costMonth) : '—'}</td><td><button class="btn sm" data-act="hrEmpEdit" data-id="${esc(r.id)}">✎</button></td></tr>`),
            `<tr><td colspan="2">Итого (${d.rows.length})</td><td class="amt num">${money(T.salary)}</td><td class="amt num">${money(T.employerCost)}</td><td></td><td class="amt num">${money(T.monthCost)}</td><td class="amt num">${T.normHours}</td><td class="amt num">${T.normHours ? money(T.monthCost / T.normHours) : '—'}</td><td class="amt num">${hz(T.hoursMonth)}</td><td class="amt num">${money(T.costMonth)}</td><td></td></tr>`);
        $('#hr-f-ym').onchange = () => { location.hash = `#/hrcost?tab=rates&ym=${$('#hr-f-ym').value}`; };
        ui.ACT.hrEmpEdit = async ({ id }) => { const c = await api('/hr/employees/' + encodeURIComponent(id)); empModal(c.employee, c); };
        bind(main); return;
      }
      const per = ['12', '26', '52', 'all'].includes(u.get('per')) ? u.get('per') : '12'; const draft = u.get('draft') === '1'; const to = HR.isoWeek(today());
      const from = per === 'all' ? 'all' : HR.addWeeks(to, -(Number(per) - 1)); const d = await api('/hr/cost?' + qsOf({ from, to, draft: draft ? '1' : '' }));
      const secChips = bs => Object.entries(bs).sort((a, b) => b[1].cost - a[1].cost).map(([s, v]) => `<span class="chip neutral" title="${money(v.cost)}">${esc(s)} ${hz(v.hours)} ч</span>`).join(' ');
      main.innerHTML = head('Ставки и себестоимость', `${per === 'all' ? 'За всё время' : `Последние ${per} недель`} · часов ${h(d.total.hours)} · себестоимость <b class="num">${money(d.total.cost)}</b>${draft ? ' · с черновиками' : ' · только сданные и принятые'}`) + tabs +
        `<div class="filters">${sel('hr-f-per', [['12', '12 недель'], ['26', '26 недель'], ['52', '52 недели'], ['all', 'Всё время']], per)}<label class="fl"><input type="checkbox" id="hr-f-draft"${draft ? ' checked' : ''}> учитывать черновики</label></div>` +
        (d.rows.length ? `<div class="tbl"><table><thead><tr><th>Проект</th><th>Стадия</th><th class="amt">Часы</th><th class="amt">Себестоимость</th><th class="amt">Ср. ставка</th><th>Разделы</th><th class="amt">Людей</th></tr></thead><tbody>${d.rows.map((r, i) => `<tr class="${r.pid ? 'hr-row' : ''}" data-pid="${esc(r.pid || '')}" data-i="${i}"><td><b>${esc(r.name)}</b>${!r.pid ? ' <span class="chip neutral">не проект</span>' : ''}</td><td>${r.track ? esc(TRACK[r.track] || r.track) : ''}</td><td class="amt num">${h(r.hours)}</td><td class="amt num"><b>${money(r.cost)}</b></td><td class="amt num">${r.hours ? money(r.cost / r.hours) : '—'}</td><td>${secChips(r.bySection)}</td><td class="amt num">${r.people}</td></tr><tr class="row-detail" data-for="${i}" hidden><td colspan="7" id="hr-det-${i}">Загрузка…</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="2">Итого</td><td class="amt num">${h(d.total.hours)}</td><td class="amt num">${money(d.total.cost)}</td><td class="amt num">${d.total.hours ? money(d.total.cost / d.total.hours) : '—'}</td><td colspan="2"></td></tr></tfoot></table></div>` : empty('Часов за период нет'));
      const nav = () => { location.hash = '#/hrcost?' + qsOf({ tab: 'projects', per: $('#hr-f-per').value, draft: $('#hr-f-draft').checked ? '1' : '' }); };
      $('#hr-f-per').onchange = nav; $('#hr-f-draft').onchange = nav;
      main.querySelectorAll('tr.hr-row').forEach(tr => tr.onclick = async () => { const det = main.querySelector(`tr[data-for="${tr.dataset.i}"]`); det.hidden = !det.hidden; if (det.hidden || det.dataset.loaded) return; det.dataset.loaded = '1';
        try { const c = await api('/hr/cost/' + encodeURIComponent(tr.dataset.pid) + '?' + qsOf({ from, to, draft: draft ? '1' : '' })); const bud = c.project.budget; const planIn = bud && bud.sections ? bud.sections.filter(s => (s.executor || '') !== 'Субподряд').reduce((s, x) => s + (Number(x.sum) || 0), 0) : 0;
          $('#hr-det-' + tr.dataset.i).innerHTML = `<div class="detail"><div class="grid g3" style="margin-bottom:10px"><div class="card"><div class="label">Часы</div><div class="val num">${h(c.hours)}</div><div class="foot">принято ${hz(c.byStatus.accepted) || 0} · сдано ${hz(c.byStatus.submitted) || 0}${draft ? ` · черновики ${hz(c.byStatus.draft) || 0}` : ''}</div></div><div class="card"><div class="label">Себестоимость часов</div><div class="val num">${money(c.cost)}</div><div class="foot">${c.weeks} недель с часами</div></div><div class="card ${planIn && c.cost > planIn ? 'crit' : ''}"><div class="label">План бюджета (внутренние разделы)</div><div class="val num">${planIn ? money(planIn) : '—'}</div><div class="foot">${planIn ? `использовано ${Math.round(c.cost / planIn * 100)} %` : 'бюджет разделов в проекте не заполнен'} · <a href="#/pmp?id=${encodeURIComponent(c.pid)}&tab=budget">карточка →</a></div></div></div><div class="grid g2"><div>${tbl([{ t: 'Сотрудник' }, { t: 'Часы', cls: 'amt' }, { t: 'Ставка', cls: 'amt' }, { t: 'Сумма', cls: 'amt' }], c.byEmployee.map(x => `<tr><td>${empLink(x.employeeId, x.name)}${x.position ? `<div class="faint">${esc(x.position)}</div>` : ''}</td><td class="amt num">${h(x.hours)}</td><td class="amt num">${money(x.rate)}</td><td class="amt num">${money(x.cost)}</td></tr>`))}</div><div>${tbl([{ t: 'Раздел' }, { t: 'Часы', cls: 'amt' }, { t: 'Сумма', cls: 'amt' }], Object.entries(c.bySection).sort((a, b) => b[1].cost - a[1].cost).map(([s, v]) => `<tr><td>${esc(s)}</td><td class="amt num">${h(v.hours)}</td><td class="amt num">${money(v.cost)}</td></tr>`))}<div style="height:10px"></div>${tbl([{ t: 'Месяц' }, { t: 'Часы', cls: 'amt' }, { t: 'Сумма', cls: 'amt' }], Object.entries(c.byMonth).sort().map(([m, v]) => `<tr><td>${esc(mname(m))}</td><td class="amt num">${h(v.hours)}</td><td class="amt num">${money(v.cost)}</td></tr>`))}</div></div></div>`; }
        catch (e) { $('#hr-det-' + tr.dataset.i).innerHTML = `<span class="crit-text">${esc(e.message)}</span>`; } });
    };
    badges(false);
  },
});
